import re

phone_numbers = ['09121234567', '021-12345678', '+989121234567', '12345']

for phone in phone_numbers:
    if re.match(r'^(\+98|0)\d{10}$', phone):
        print(f'{phone}: Iranian mobile')
    elif re.match(r'^0\d{2}-?\d{8}$', phone):
        print(f'{phone}: Iranian landline')
    else:
        print(f'{phone}: Unknown format')
